package io.github.jesterportfolio.hearth.survival;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;import io.github.jesterportfolio.hearth.survival.platform.*;
class PlatformOperationsTest {
 @TempDir Path root;
 @Test void terminalConfigurationMovesWithArchivesAndArchivedIdRemainsStable()throws Exception{Files.writeString(root.resolve("platform.properties"),"old");Files.writeString(root.resolve("next.candidate"),"new");var c=new ConfigurationChanges(root);var plan=c.stage("platform.properties","next.candidate",(n,a,b)->{});assertThrows(Exception.class,()->c.archive(plan));c.publish(plan,false,(n,a,b)->{});c.mark(plan,"COMMITTED");c.archive(plan);assertTrue(c.scan().plans().isEmpty());var saved=new ConfigurationChanges(root).plan(plan.id());assertTrue(c.archived(saved));assertFalse(c.hot(plan.id()));assertEquals(plan.before(),saved.before());assertEquals("old",Files.readString(saved.directory().resolve("before")));c.archive(saved);assertEquals("new",Files.readString(root.resolve("platform.properties")));}
 @Test void vaultMoveResumeAndRestorePreserveWholeWorld()throws Exception{var v=new ResourceVault(root);String key="hearth_resource:r_novice_"+"a".repeat(32);Path source=v.source(key);Files.createDirectories(source.resolve("region"));Files.writeString(source.resolve("region/r.0.0.mca"),"world bytes");UUID id=UUID.randomUUID();String seal=v.seal(source);v.move(key,id,seal,false);assertFalse(Files.exists(source));assertEquals(seal,v.seal(v.cold(id)));v.move(key,id,seal,false);v.move(key,id,seal,true);assertEquals(seal,v.seal(source));assertFalse(Files.exists(v.cold(id)));}
 @Test void vaultRejectsChangedLinksAmbiguityAndBaseWorlds()throws Exception{var v=new ResourceVault(root);assertThrows(Exception.class,()->v.source("hearth_survival:residence"));String key="hearth_resource:r_end_"+"b".repeat(32);var p=v.source(key);Files.createDirectories(p);Files.writeString(p.resolve("data"),"one");String seal=v.seal(p);Files.writeString(p.resolve("data"),"two");assertThrows(Exception.class,()->v.move(key,UUID.randomUUID(),seal,false));Files.createSymbolicLink(p.resolve("link"),p.resolve("data"));assertThrows(Exception.class,()->v.seal(p));}
 @Test void queuedFileWorkIsOrderedOffCallerAndClosedWorkerRefusesNewWork()throws Exception{var io=new PlatformIo();String caller=Thread.currentThread().getName();var order=new CopyOnWriteArrayList<Integer>();var a=io.submit(()->{assertNotEquals(caller,Thread.currentThread().getName());order.add(1);return 1;});var b=io.submit(()->{order.add(2);return 2;});assertEquals(1,a.toCompletableFuture().get(3,TimeUnit.SECONDS));assertEquals(2,b.toCompletableFuture().get(3,TimeUnit.SECONDS));assertEquals(List.of(1,2),order);io.close();assertThrows(ExecutionException.class,()->io.submit(()->3).toCompletableFuture().get());}
 @Test void maintenanceKeepsRecoveryButClosesGameAndDispatch(){var g=new PlatformGate(true,false,true,false,false,false,true,true,true,true);assertFalse(g.operational());assertFalse(g.dispatch());assertTrue(g.configuration());}
 @Test void controllerHoldAndConfigurationWorkBlockDispatch(){for(int i=0;i<3;i++){var g=new PlatformGate(true,false,false,false,false,false,true,i!=0,i!=1,i!=2);assertFalse(g.dispatch());}assertFalse(new PlatformGate(true,false,false,true,false,false,true,true,true,true).dispatch());assertFalse(new PlatformGate(true,true,false,false,false,false,true,true,true,true).configuration());assertFalse(new PlatformGate(true,false,false,false,false,false,false,true,true,true).configuration());}
}
